import React from "react";
import { motion } from "framer-motion";
import AboutUs from "./AboutUs";
import ContactUs from "./ContactUs";
import Gallery from "./Gallery";
import "./../styles.css";

const Home = () => {

  const scrollToGallery = () => {
    const gallerySection = document.getElementById("gallery");
    if (gallerySection) {
      gallerySection.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <div>
      <motion.section
        className="home-section"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        transition={{ duration: 1 }}
        id="home"
      >


        <div className="hero-banner row">
          <div className="row">
            <h1 className="home-title">Welcome to Craftify</h1>
          </div>
          <div className="row">
            <div className="col-12 col-md-6">
              <p>Craftify is a platform dedicated to showcasing the beauty and uniqueness of handmade crafts.
                Our goal is to connect talented artisans with people who appreciate handcrafted goods.
                Each item tells a story, reflecting the passion and skill of the artist behind it.
                From handwoven fabrics to intricately designed pottery, we celebrate craftsmanship in its purest form.
                We believe that handmade products bring warmth and authenticity to every home. </p>
            </div>

            <div className="col-12 col-md-6 ">
              <p>
                Our carefully curated collection represents diverse cultures, traditions, and artistic techniques.
                Whether you're looking for a unique gift or a decorative piece, you'll find something special here.
                Supporting handmade crafts helps preserve centuries-old traditions and provides fair wages to artisans.
                We collaborate with artists worldwide to bring you exclusive, high-quality pieces.
                Browse our collection, get inspired, and experience the magic of handmade art today!</p>
              <button className="explore-btn" onClick={() => scrollToGallery()}>Explore Now</button>
            </div>
          </div>




        </div>
      </motion.section>

      <motion.section
        id="about"
        initial={{ x: "-100vw" }}
        animate={{ x: 0 }}
        transition={{ type: "spring", stiffness: 50 }}
      >
        <AboutUs />
      </motion.section>

      <motion.section
        id="gallery"
        initial={{ opacity: 0, y: 50 }}
        whileInView={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
        viewport={{ once: true }}
      >
        <Gallery />
      </motion.section>

      <motion.section
        id="contact"
        initial={{ scale: 0.8 }}
        animate={{ scale: 1 }}
        transition={{ duration: 0.5 }}
      >
        <ContactUs />
      </motion.section>



    </div>



  );
};

export default Home;
